import httpx

try:
    response = httpx.get("https://example.com")
    response.raise_for_status()
    print(response.json())
except httpx.RequestError as exc:
    print(f"Request failed: {exc.request.url!r}")
except httpx.HTTPStatusError as exc:
    print(f"HTTP error {exc.response.status_code}: {exc.request.url!r}")

