import httpx

try:
    response = httpx.get("https://example.com", timeout=2.0)
    response.raise_for_status()
except httpx.ReadTimeout:
    print("The server did not send data in time.")
except httpx.HTTPError as exc:
    print(f"HTTPX error: {exc}")
